import { RoleChange } from "@/components/ui/role-change";

export function Access() {
  return (
    <RoleChange
      title="Rôles d'accès – Formulaires"
      target="app_formulaires.membres"
      rows={[
        { id: "1", name: "Camille Durand", before: "Lecteur", after: "Éditeur" },
        { id: "2", name: "Hugo Martin", before: "Aucun accès", after: "Lecteur" },
      ]}
      onApply={(rows) => api.updateRoles(rows)}
      onUndo={(rows) => api.revertRoles(rows)}
    />
  );
}
